import { createRoute, z } from '@hono/zod-openapi'

const ScheduleRuleSchema = z
  .strictObject({
    enabled: z
      .boolean()
      .openapi({
        description: 'Whether the rule should be enabled or disabled at the specified timestamp.',
      }),
    timestamp: z
      .union([z.iso.datetime({ offset: true }), z.null().nullable()])
      .openapi({ description: 'ISO timestamp when the rule should activate.' }),
  })
  .openapi({ required: ['enabled', 'timestamp'] })
  .openapi('ScheduleRule')

const FeatureForceRuleSchema = z
  .strictObject({
    description: z.string().max(10000),
    condition: z.string().exactOptional(),
    id: z.string(),
    enabled: z.boolean(),
    scheduleRules: z
      .array(ScheduleRuleSchema)
      .exactOptional()
      .openapi({ description: 'Simple time-based on/off schedule for this rule' }),
    scheduleType: z
      .enum(['none', 'schedule', 'ramp'])
      .exactOptional()
      .openapi({
        description:
          'UI hint for which scheduling mode is active:\n- `none` – no schedule\n- `schedule` – simple time-based enable/disable via `scheduleRules`\n- `ramp` – multi-step ramp-up controlled by an associated RampSchedule document\n',
      }),
    rampScheduleId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'ID of the active RampSchedule document controlling this rule. Present when `scheduleType` is `ramp` and a live schedule exists.',
      }),
    savedGroupTargeting: z
      .array(
        z
          .strictObject({
            matchType: z.enum(['all', 'any', 'none']),
            savedGroups: z.array(z.string()),
          })
          .openapi({ required: ['matchType', 'savedGroups'] }),
      )
      .exactOptional(),
    prerequisites: z
      .array(
        z
          .strictObject({
            id: z.string().openapi({ description: 'Feature ID of the prerequisite' }),
            condition: z.string(),
          })
          .openapi({ required: ['id', 'condition'] }),
      )
      .exactOptional(),
    allProjects: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'When true (the default) the rule applies to every project the feature is delivered to. When false the rule is limited to `projects`.',
      }),
    projects: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Project IDs this rule is scoped to when `allProjects` is false. An empty array scopes the rule to no project.',
      }),
  })
  .openapi({
    description:
      'Common fields shared by all feature rule types. Specific rule types extend\nthis base with their own required properties (value, coverage, etc.).\n',
    required: ['description', 'id', 'enabled'],
  })
  .and(
    z
      .strictObject({
        type: z.literal('force'),
        value: z.string(),
        sparse: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              "JSON features only. When true, `value` is a partial object merged onto the feature's default value instead of replacing it.",
          }),
      })
      .openapi({ required: ['type', 'value'] }),
  )
  .openapi('FeatureForceRule')

const FeatureRolloutRuleSchema = z
