const TargetingRuleSchema = z
  .strictObject({
    description: z
      .string()
      .exactOptional()
      .openapi({ description: 'Short note on why the rule exists (e.g. `Beta testers only`).' }),
    enabled: z.boolean().exactOptional(),
    condition: z.string().exactOptional(),
    savedGroups: z
      .array(
        z
          .strictObject({ match: z.enum(['all', 'none', 'any']), ids: z.array(z.string()) })
          .openapi({ required: ['match', 'ids'] }),
      )
      .exactOptional(),
    prerequisites: z
      .array(
        z
          .strictObject({ id: z.string(), condition: z.string() })
          .openapi({ required: ['id', 'condition'] }),
      )
      .exactOptional(),
    allEnvironments: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'When true the rule applies to all environments. Omit both scope fields to apply to all environments.',
      }),
    environments: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Environment IDs the rule applies to. Ignored when allEnvironments is true; with allEnvironments false, an omitted or empty list scopes the rule to no environment.',
      }),
    type: z
      .enum(['force', 'rollout'])
      .exactOptional()
      .openapi({
        description:
          'Use "force" for a standard targeting rule, or "rollout" for a percentage rollout (coverage < 1). Defaults to "force". Both are functionally equivalent; a force rule with coverage < 1 behaves as a rollout.',
      }),
    value: z.string().openapi({ description: 'The value to serve when this rule matches.' }),
    config: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Key of a config to back this value. When set, `value` is a JSON override patch merged on top of the config; omit or null for a plain value.',
      }),
    sparse: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "JSON features only. When true, the rule value is a partial object merged onto the feature's default value instead of replacing it.",
      }),
    coverage: z
      .number()
      .min(0)
      .max(1)
      .exactOptional()
      .openapi({
        description:
          'Percentage of users to include (0–1). Defaults to 1. When less than 1, hashAttribute is required.',
      }),
    hashAttribute: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Attribute to hash on for consistent assignment. Required when coverage < 1.',
      }),
    fallbackAttribute: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Used in place of `hashAttribute` when a user lacks it. Only SDKs with Sticky Bucketing enabled use it.',
      }),
    seed: z.string().exactOptional(),
    hashVersion: z
      .union([z.literal(1), z.literal(2)])
      .exactOptional()
      .openapi({
        description:
          'Hash algorithm version for bucketing. Defaults to 2 (preferred) when not specified.',
      }),
  })
  .openapi({
    description:
      'A targeting rule that serves a specific value to users matching the conditions. Set coverage < 1 for a percentage rollout.',
    required: ['value'],
  })
  .openapi('TargetingRule')

