const ScheduledStopPlanSchema = z
  .strictObject({
    mode: z.enum(['notify', 'auto-ship', 'force-ship', 'stop']),
    tiebreakerMetricId: z.string().exactOptional(),
    fallback: z
      .enum(['notify', 'force-ship'])
      .exactOptional()
      .openapi({
        description:
          'What to do at the scheduled end when there is no clear winner. Required when `mode` is `"auto-ship"`; ignored for other modes.',
      }),
    fallbackVariationId: z.string().exactOptional(),
  })
  .openapi({
    description:
      'What happens at the scheduled end date. `notify` keeps the experiment running and just notifies (soft). `auto-ship` (requires the Decision Framework) ships the winning variation and stops; multi-winner ties break on `tiebreakerMetricId` (higher lift); with no clear winner, `fallback` either keeps running (`notify`) or ships `fallbackVariationId`. `force-ship` stops and rolls out `fallbackVariationId`. `stop` is a hard deadline that stops with no rollout. For `force-ship` and `stop`, the Decision Framework verdict (won/lost/inconclusive) is recorded as metadata when available.',
    required: ['mode'],
  })
  .openapi('ScheduledStopPlan')

const ExperimentSchema = z
  .strictObject({
    id: z.string(),
    trackingKey: z.string(),
    dateCreated: z.iso.datetime({ offset: true }),
    dateUpdated: z.iso.datetime({ offset: true }),
    name: z.string(),
    type: z.enum(['standard', 'multi-armed-bandit', 'holdout']),
    project: z.string(),
    hypothesis: z.string(),
    description: z.string().max(10000),
    tags: z.array(z.string()),
    owner: z
      .string()
      .openapi({
        description: 'The userId of the owner (or raw owner name/email for legacy records)',
      }),
    ownerEmail: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The email address of the owner, when the owner can be resolved to a known user.',
      }),
    archived: z.boolean(),
    status: z.string(),
    autoRefresh: z.boolean(),
    hashAttribute: z.string(),
    fallbackAttribute: z.string().exactOptional(),
    hashVersion: z.union([z.literal(1), z.literal(2)]),
    disableStickyBucketing: z.boolean().exactOptional(),
    bucketVersion: z.number().exactOptional(),
    minBucketVersion: z.number().exactOptional(),
    variations: z.array(
      z
        .strictObject({
          variationId: z.string(),
          key: z.string(),
          name: z.string(),
          description: z.string().max(10000),
          screenshots: z.array(z.string()),
        })
        .openapi({ required: ['variationId', 'key', 'name', 'description', 'screenshots'] }),
    ),
    phases: z.array(
      z
        .strictObject({
          name: z.string(),
          dateStarted: z.string(),
          dateEnded: z.string(),
          reasonForStopping: z.string(),
          seed: z.string(),
          coverage: z.number(),
          trafficSplit: z.array(
            z
              .strictObject({ variationId: z.string(), weight: z.number() })
              .openapi({ required: ['variationId', 'weight'] }),
          ),
          namespace: z
            .strictObject({
              namespaceId: z.string(),
              enabled: z.boolean().exactOptional(),
              range: z.array(z.number()).length(2).exactOptional(),
              ranges: z
                .array(
                  z.array(z.unknown()).superRefine((arr, ctx) => {
                    const Prefix = [z.number(), z.number()]
                    for (const [i, Schema] of Prefix.slice(0, arr.length).entries()) {
                      const result = Schema.safeParse(arr[i])
                      if (!result.success) {
                        for (const issue of result.error.issues) {
                          ctx.addIssue({ ...issue, path: [i, ...issue.path] })
                        }
                      }
                    }
                  }),
                )
                .exactOptional(),
            })
            .exactOptional()
            .openapi({ required: ['namespaceId'] }),
          targetingCondition: z.string(),
          prerequisites: z
            .array(
              z
                .strictObject({ id: z.string(), condition: z.string() })
                .openapi({ required: ['id', 'condition'] }),
            )
            .exactOptional(),
          savedGroupTargeting: z
            .array(
              z
                .strictObject({
                  matchType: z.enum(['all', 'any', 'none']),
                  savedGroups: z.array(z.string()),
                })
                .openapi({ required: ['matchType', 'savedGroups'] }),
            )
            .exactOptional(),
        })
        .openapi({
          required: [
            'name',
            'dateStarted',
            'dateEnded',
            'reasonForStopping',
            'seed',
            'coverage',
            'trafficSplit',
            'targetingCondition',
          ],
        }),
    ),
    settings: ExperimentAnalysisSettingsSchema,
    resultSummary: z
      .strictObject({
        status: z.string(),
        winner: z.string(),
        conclusions: z.string(),
        releasedVariationId: z.string(),
        excludeFromPayload: z.boolean(),
      })
      .exactOptional()
      .openapi({
        required: ['status', 'winner', 'conclusions', 'releasedVariationId', 'excludeFromPayload'],
      }),
    shareLevel: z.enum(['public', 'organization']).exactOptional(),
    publicUrl: z.string().exactOptional(),
    banditScheduleValue: z.number().exactOptional(),
    banditScheduleUnit: z.enum(['days', 'hours']).exactOptional(),
    banditBurnInValue: z.number().exactOptional(),
    banditBurnInUnit: z.enum(['days', 'hours']).exactOptional(),
    banditConversionWindowValue: z.number().exactOptional(),
    banditConversionWindowUnit: z.enum(['days', 'hours']).exactOptional(),
    linkedFeatures: z.array(z.string()).exactOptional(),
    attributeScopeAllProjects: z.boolean().exactOptional(),
    hasVisualChangesets: z.boolean().exactOptional(),
    hasURLRedirects: z.boolean().exactOptional(),
    customFields: z.record(z.string(), z.any()).exactOptional(),
    customMetricSlices: z
      .array(
        z
          .strictObject({
            slices: z.array(
              z
                .strictObject({ column: z.string(), levels: z.array(z.string()) })
                .openapi({ required: ['column', 'levels'] }),
            ),
          })
          .openapi({ required: ['slices'] }),
      )
      .exactOptional()
      .openapi({
        description: 'Custom slices that apply to ALL applicable metrics in the experiment',
      }),
    precomputedUnitDimensionIds: z.array(z.string()).max(3).exactOptional(),
    defaultDashboardId: z
      .string()
      .exactOptional()
      .openapi({ description: 'ID of the default dashboard for this experiment.' }),
    templateId: z.string().exactOptional(),
    statusUpdateSchedule: z
      .union([
        z
          .strictObject({
            startAt: z.iso
              .datetime({ offset: true })
              .exactOptional()
              .openapi({
                description:
                  'ISO datetime when the experiment should start. Must be in the future. Setting or clearing this field invalidates any existing staged start (`nextScheduledStatusUpdate`); call POST /experiments/{id}/start to stage the new schedule.',
              }),
            stopAt: z.iso
              .datetime({ offset: true })
              .exactOptional()
              .openapi({
                description:
                  'ISO datetime when the experiment should stop. Resolved from `stopAfter` at start when a relative end was set.',
              }),
            stopAfter: z
              .strictObject({ value: z.int().gt(0), unit: z.enum(['hours', 'days']) })
              .exactOptional()
              .openapi({
                description:
                  "Relative end offset. Deferred: resolved to a concrete `stopAt` at the experiment's actual start (or off `dateStarted` when already running).",
                required: ['value', 'unit'],
              }),
            scheduledStopPlan: ScheduledStopPlanSchema.exactOptional().openapi({
              description:
                'End-of-experiment automation applied at the scheduled end. Required whenever a `stopAt` or `stopAfter` is set (any mode, including `notify`).',
            }),
          })
          .openapi({
            description:
              'Scheduled start/end for an experiment. All fields optional; the end may be an absolute `stopAt` or a deferred relative `stopAfter`, but not both.',
            required: [],
          }),
        z.null().nullable(),
      ])
      .exactOptional(),
    nextScheduledStatusUpdate: z
      .union([
        z
          .strictObject({ type: z.enum(['start', 'stop']), date: z.iso.datetime({ offset: true }) })
          .openapi({ required: ['type', 'date'] }),
        z.null().nullable(),
      ])
      .exactOptional(),
  })
  .openapi({
    required: [
      'id',
      'trackingKey',
      'dateCreated',
      'dateUpdated',
      'name',
      'type',
      'project',
      'hypothesis',
      'description',
      'tags',
      'owner',
      'archived',
      'status',
      'autoRefresh',
      'hashAttribute',
      'hashVersion',
      'variations',
      'phases',
      'settings',
    ],
  })
  .openapi('Experiment')

