const SavedGroupUploadSchema = z
  .strictObject({
    savedGroupId: z.string(),
    version: z.int(),
    fileName: z
      .union([z.string(), z.null().nullable()])
      .openapi({ description: "The uploaded file's original name, if it was given" }),
    size: z.int().openapi({ description: 'File size in bytes' }),
    sha256: z
      .union([z.string(), z.null().nullable()])
      .openapi({
        description:
          "Hex SHA-256 of the file, set once it's validated. Null if it isn't validated yet, or wasn't read in full.",
      }),
    dateCreated: z.iso.datetime({ offset: true }),
    createdBy: z
      .string()
      .openapi({
        description:
          'Who uploaded it: a user ID, or an API key ID (`key_…`) for a key acting as itself',
      }),
    status: z
      .union([
        z.strictObject({ type: z.literal('pending') }).openapi({ required: ['type'] }),
        z
          .strictObject({
            type: z.literal('valid'),
            idCount: z
              .int()
              .min(0)
              .openapi({ description: 'IDs in the file, before removing duplicates' }),
          })
          .openapi({ required: ['type', 'idCount'] }),
        z
          .strictObject({
            type: z.literal('invalid'),
            invalidLineCount: z.int().min(0),
            errors: z
              .array(z.string().max(500))
              .max(10)
              .openapi({ description: 'The first problems found in the file' }),
          })
          .openapi({ required: ['type', 'invalidLineCount', 'errors'] }),
      ])
      .openapi({
        description:
          '`pending` until GrowthBook has checked the whole file. Loaders only see `valid` uploads.',
      }),
    loads: z
      .array(
        z
          .strictObject({
            storeId: z
              .string()
              .min(1)
              .max(100)
              .openapi({
                description:
                  "The data store's ID, such as `redis-us-east`, set in the loader's config. Loaders sharing a store (such as one Redis) use the same ID. Shown in the UI.",
              }),
            status: z
              .union([
                z.strictObject({ type: z.literal('loading') }).openapi({ required: ['type'] }),
                z
                  .strictObject({
                    type: z.literal('loaded'),
                    rowCount: z.int().min(0).openapi({ description: 'Unique IDs loaded' }),
                  })
                  .openapi({ required: ['type', 'rowCount'] }),
                z
                  .strictObject({
                    type: z.literal('invalid'),
                    invalidLineCount: z.int().min(0),
                    errors: z
                      .array(z.string().max(500))
                      .max(10)
                      .openapi({ description: 'The first problems found in the file' }),
                  })
                  .openapi({
                    description:
                      'The file has problems, so the store kept serving the previous upload',
                    required: ['type', 'invalidLineCount', 'errors'],
                  }),
                z
                  .strictObject({
                    type: z.literal('failed'),
                    error: z
                      .string()
                      .max(2000)
                      .openapi({ description: 'A problem in the data store, not the file' }),
                  })
                  .openapi({ required: ['type', 'error'] }),
              ])
              .openapi({
                description:
                  'Loaders validate the file while loading it, so each store reports its own result.',
              }),
            dateUpdated: z.iso.datetime({ offset: true }),
          })
          .openapi({ required: ['storeId', 'status', 'dateUpdated'] }),
      )
      .openapi({ description: "Each data store's latest report on loading this upload" }),
  })
  .openapi({
    required: [
      'savedGroupId',
      'version',
      'fileName',
      'size',
      'sha256',
      'dateCreated',
      'createdBy',
      'status',
      'loads',
    ],
  })
  .openapi('SavedGroupUpload')

