const ConfigRevisionActivityLogEntrySchema = z
  .strictObject({
    id: z.string(),
    userId: z
      .string()
      .openapi({
        description: "Who acted: a member's user ID, or an API key's ID when it acted as itself",
      }),
    action: z.enum([
      'created',
      'updated',
      'reviewed',
      'approved',
      'requested-changes',
      'commented',
      'review-requested',
      'review-retracted',
      'merged',
      'discarded',
      'reopened',
      'recalled',
      'scheduled-publish',
      'scheduled-publish-updated',
      'scheduled-publish-canceled',
      'merge-recovered',
    ]),
    description: z.union([z.string(), z.null().nullable()]).exactOptional(),
    proposedChangesSnapshot: z
      .array(
        z.union([
          z
            .strictObject({
              op: z.literal('add'),
              path: z.string().regex(/^\/[^\/]+$/),
              value: z.any(),
            })
            .openapi({ required: ['op', 'path', 'value'] }),
          z
            .strictObject({ op: z.literal('remove'), path: z.string().regex(/^\/[^\/]+$/) })
            .openapi({ required: ['op', 'path'] }),
          z
            .strictObject({
              op: z.literal('replace'),
              path: z.string().regex(/^\/[^\/]+$/),
              value: z.any(),
            })
            .openapi({ required: ['op', 'path', 'value'] }),
          z
            .strictObject({
              op: z.literal('move'),
              from: z.string().regex(/^\/[^\/]+$/),
              path: z.string().regex(/^\/[^\/]+$/),
            })
            .openapi({ required: ['op', 'from', 'path'] }),
          z
            .strictObject({
              op: z.literal('copy'),
              from: z.string().regex(/^\/[^\/]+$/),
              path: z.string().regex(/^\/[^\/]+$/),
            })
            .openapi({ required: ['op', 'from', 'path'] }),
          z
            .strictObject({
              op: z.literal('test'),
              path: z.string().regex(/^\/[^\/]+$/),
              value: z.any(),
            })
            .openapi({ required: ['op', 'path', 'value'] }),
        ]),
      )
      .exactOptional(),
    targetSnapshot: z.any().exactOptional(),
    dateCreated: z.iso.datetime({ offset: true }),
    user: EventUserSchema.exactOptional(),
  })
  .openapi({ required: ['id', 'userId', 'action', 'dateCreated'] })
  .openapi('ConfigRevisionActivityLogEntry')

const ConfigRevisionSchema = z
  .strictObject({
    id: z.string(),
    version: z.int().exactOptional(),
    title: z.string().exactOptional(),
    status: z.enum([
      'draft',
      'pending-review',
      'approved',
      'changes-requested',
      'merged',
      'discarded',
    ]),
    authorId: z
      .string()
      .openapi({
        description: "Who acted: a member's user ID, or an API key's ID when it acted as itself",
      }),
    author: EventUserSchema.exactOptional().openapi({
      description: "Who created the revision, with an API key's name",
    }),
    authorEmail: z.string().exactOptional(),
    contributors: z.array(z.string()).exactOptional(),
    revertedFrom: z.string().exactOptional(),
    reviews: z.array(ConfigRevisionReviewSchema),
    activityLog: z.array(ConfigRevisionActivityLogEntrySchema),
    autoPublishOnApproval: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Publish automatically the moment this revision is approved.' }),
    autoPublishEnabledBy: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "User or API key the deferred publish runs as, re-checked when it fires. A key that assumed a member's role is recorded as `<keyId>:<memberId>`.",
      }),
    autoPublishEnabledByUser: EventUserSchema.exactOptional().openapi({
      description: "Who armed the deferred publish, with an API key's name",
    }),
    scheduledPublishAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'When the deferred publish fires. Absent when the revision publishes on approval instead, or is not armed at all.',
      }),
    scheduledPublishLockEdits: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Content edits to this revision are frozen until it fires.' }),
    scheduledPublishLockOthers: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Other revisions of the same resource cannot publish until this one fires or is cancelled.',
      }),
    scheduledPublishBypassApproval: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Armed by a caller who bypassed the approval requirement. Such a schedule must be cancelled and re-armed rather than edited.',
      }),
    scheduledPublishAttempts: z
      .int()
      .exactOptional()
      .openapi({ description: 'How many times the poller has tried to publish this revision.' }),
    scheduledPublishLastError: z
      .string()
      .exactOptional()
      .openapi({ description: 'Why the most recent deferred-publish attempt failed.' }),
    scheduledPublishGaveUpAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'When the poller stopped retrying. Giving up CLEARS the schedule and disarms auto-publish, so nothing fires again until the revision is re-armed. The draft is left open, with `scheduledPublishLastError` preserved for context.',
      }),
    resolution: z
      .strictObject({
        action: z.enum(['merged', 'discarded']),
        userId: z
          .string()
          .openapi({
            description:
              "Who acted: a member's user ID, or an API key's ID when it acted as itself",
          }),
        user: EventUserSchema.exactOptional(),
        dateCreated: z.iso.datetime({ offset: true }),
      })
      .exactOptional()
      .openapi({ required: ['action', 'userId', 'dateCreated'] }),
    dateCreated: z.iso.datetime({ offset: true }),
    dateUpdated: z.iso.datetime({ offset: true }),
    baseConfig: ConfigSchema,
    proposedConfig: ConfigSchema,
    proposedChanges: z.array(
      z.union([
        z
          .strictObject({
            op: z.literal('add'),
            path: z.string().regex(/^\/[^\/]+$/),
            value: z.any(),
          })
          .openapi({ required: ['op', 'path', 'value'] }),
        z
          .strictObject({ op: z.literal('remove'), path: z.string().regex(/^\/[^\/]+$/) })
          .openapi({ required: ['op', 'path'] }),
        z
          .strictObject({
            op: z.literal('replace'),
            path: z.string().regex(/^\/[^\/]+$/),
            value: z.any(),
          })
          .openapi({ required: ['op', 'path', 'value'] }),
        z
          .strictObject({
            op: z.literal('move'),
            from: z.string().regex(/^\/[^\/]+$/),
            path: z.string().regex(/^\/[^\/]+$/),
          })
          .openapi({ required: ['op', 'from', 'path'] }),
        z
          .strictObject({
            op: z.literal('copy'),
            from: z.string().regex(/^\/[^\/]+$/),
            path: z.string().regex(/^\/[^\/]+$/),
          })
          .openapi({ required: ['op', 'from', 'path'] }),
        z
          .strictObject({
            op: z.literal('test'),
            path: z.string().regex(/^\/[^\/]+$/),
            value: z.any(),
          })
          .openapi({ required: ['op', 'path', 'value'] }),
      ]),
    ),
  })
  .openapi({
    required: [
      'id',
      'status',
      'authorId',
      'reviews',
      'activityLog',
      'dateCreated',
      'dateUpdated',
      'baseConfig',
      'proposedConfig',
      'proposedChanges',
    ],
  })
  .openapi('ConfigRevision')

