const RampScheduleTemplateSchema = z
  .strictObject({
    id: z.string(),
    dateCreated: z.iso.datetime({ offset: true }),
    dateUpdated: z.iso.datetime({ offset: true }),
    name: z.string(),
    steps: z.array(
      z
        .strictObject({
          interval: z
            .union([z.number().gt(0), z.null().nullable()])
            .openapi({
              description:
                "Hold duration in seconds before this step's gates are evaluated. null = no time gate (advance as soon as holdConditions clear).",
            }),
          approvalNotes: z.union([z.string(), z.null().nullable()]).exactOptional(),
          monitored: z
            .boolean()
            .exactOptional()
            .openapi({
              description:
                'When true, this step runs A/B traffic analysis while active. Treatment = [0, coverage), control = [0.5, 0.5+coverage). Arms are equal-sized and non-adjacent: step-ups only add users, never reassign existing ones. The UI caps monitored-step coverage at 0.5 so control end never exceeds 1.0. The SDK uses explicit hash ranges on the experiment rule to prevent bucketing shifts across monitored/unmonitored transitions.',
            }),
          holdConditions: z
            .strictObject({
              minSampleSize: z.int().gt(0).exactOptional(),
              requiresApproval: z.boolean().exactOptional(),
            })
            .exactOptional()
            .openapi({ required: [] }),
          actions: z.array(
            z
              .strictObject({
                targetType: z.literal('feature-rule'),
                targetId: z.string(),
                patch: z
                  .strictObject({
                    ruleId: z.string(),
                    coverage: z
                      .union([z.number().min(0).max(1), z.null().nullable()])
                      .exactOptional()
                      .openapi({
                        description:
                          'Traffic fraction (0–1). For monitored steps the rollout rule is promoted to an experiment: treatment = [0, coverage), control = [0.5, 0.5+coverage). Both arms are equal-sized and non-adjacent, so a step-up only adds new users to each arm — no existing user changes group. The REST API enforces coverage ≤ 0.5 on monitored steps so control end never exceeds 1.0. The SDK uses explicit hash ranges on bucketingV2 clients to keep bucketing stable across monitored/unmonitored transitions.',
                      }),
                    condition: z.union([z.string(), z.null().nullable()]).exactOptional(),
                    savedGroups: z
                      .union([
                        z.array(
                          z
                            .strictObject({
                              match: z.enum(['all', 'none', 'any']),
                              ids: z.array(z.string()),
                            })
                            .openapi({ required: ['match', 'ids'] }),
                        ),
                        z.null().nullable(),
                      ])
                      .exactOptional(),
                    prerequisites: z
                      .union([
                        z.array(
                          z
                            .strictObject({ id: z.string(), condition: z.string() })
                            .openapi({ required: ['id', 'condition'] }),
                        ),
                        z.null().nullable(),
                      ])
                      .exactOptional(),
                    allEnvironments: z.union([z.boolean(), z.null().nullable()]).exactOptional(),
                    environments: z
                      .union([z.array(z.string()), z.null().nullable()])
                      .exactOptional(),
                    enabled: z.union([z.boolean(), z.null().nullable()]).exactOptional(),
                    force: z
                      .any()
                      .exactOptional()
                      .openapi({
                        description:
                          "Ignored: templates never carry force values. Accepted so a schedule's steps can be copied into a template.",
                      }),
                  })
                  .openapi({ required: ['ruleId'] }),
              })
              .openapi({ required: ['targetType', 'targetId', 'patch'] }),
          ),
        })
        .openapi({ required: ['interval', 'actions'] }),
    ),
    endPatch: z
      .strictObject({
        coverage: z.number().min(0).max(1).exactOptional(),
        condition: z.string().exactOptional(),
        savedGroups: z
          .array(
            z
              .strictObject({ match: z.enum(['all', 'none', 'any']), ids: z.array(z.string()) })
              .openapi({ required: ['match', 'ids'] }),
          )
          .exactOptional(),
        prerequisites: z
          .array(
            z
              .strictObject({ id: z.string(), condition: z.string() })
              .openapi({ required: ['id', 'condition'] }),
          )
          .exactOptional(),
        allEnvironments: z.boolean().exactOptional(),
        environments: z.array(z.string()).exactOptional(),
      })
      .exactOptional()
      .openapi({ required: [] }),
    official: z.boolean().exactOptional(),
    monitoringConfig: z
      .union([
        z
          .strictObject({
            datasourceId: z.string(),
            guardrailMetricIds: z.array(z.string()).min(1),
            signalMetricIds: z.array(z.string()).exactOptional(),
            updateScheduleMinutes: z
              .union([z.number().min(10), z.null().nullable()])
              .exactOptional(),
            monitoringMode: z.enum(['auto', 'manual']).exactOptional(),
            autoUpdate: z.boolean().exactOptional(),
            srmAction: z.enum(['rollback', 'hold', 'warn']).exactOptional(),
            noTrafficAction: z.enum(['rollback', 'hold', 'warn']).exactOptional(),
            noTrafficGracePeriodHours: z
              .union([z.number().gt(0), z.null().nullable()])
              .exactOptional()
              .openapi({
                description:
                  'How long to wait for traffic before applying `noTrafficAction`. Defaults to 24 hours when null or not set.',
              }),
            multipleExposureAction: z.enum(['rollback', 'hold', 'warn']).exactOptional(),
            exposureQuery: z
              .strictObject({
                id: z
                  .string()
                  .openapi({
                    description: "The ID of one of the data source's assignment queries.",
                  }),
                identifierType: z
                  .union([z.string(), z.null().nullable()])
                  .openapi({
                    description:
                      'The identifier type analyzed on. Null when none can be resolved: no assignment query is selected, or a record saved before identifier types were stored points at a query that no longer exists.',
                  }),
              })
              .openapi({
                description:
                  'The assignment query, grouping its ID with the identifier type analyzed on.',
                required: ['id', 'identifierType'],
              }),
            exposureQueryId: z
              .string()
              .openapi({ description: 'Deprecated: use `exposureQuery`.', deprecated: true }),
          })
          .openapi({
            required: ['datasourceId', 'guardrailMetricIds', 'exposureQuery', 'exposureQueryId'],
          }),
        z.null().nullable(),
      ])
      .exactOptional(),
    lockdownConfig: z
      .union([
        z.strictObject({ mode: z.enum(['none', 'locked']) }).openapi({ required: ['mode'] }),
        z.null().nullable(),
      ])
      .exactOptional(),
    order: z
      .number()
      .openapi({
        description: 'Manual display order within the org (read-only; managed via the app).',
      }),
  })
  .openapi({ required: ['id', 'dateCreated', 'dateUpdated', 'name', 'steps', 'order'] })
  .openapi('RampScheduleTemplate')

