export const getV1FeaturesIdRoute = createRoute({
  method: 'get',
  path: '/v1/features/{id}',
  tags: ['features'],
  summary: 'Get a single feature',
  description: '**Deprecated.** Use [GET /v2/features/:id](#operation/getFeatureV2) instead.',
  operationId: 'getFeature',
  request: {
    params: z.object({ id: IdParamsSchema }),
    query: z.object({ withRevisions: WithRevisionsParamsSchema }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z
            .strictObject({ feature: FeatureWithRevisionsV1Schema })
            .openapi({ required: ['feature'] }),
        },
      },
    },
  },
  deprecated: true,
})

