export const getV2FeatureRevisionsRoute = createRoute({
  method: 'get',
  path: '/v2/feature-revisions',
  tags: ['feature-revisions-v2'],
  summary: 'List revisions across all features',
  description:
    'Returns a paginated list of feature revisions across all features in the organization. Use the `featureId` query parameter to filter to a single feature. Revision `rules` is a flat array with per-rule scope.',
  operationId: 'listRevisionsV2',
  request: {
    query: z.object({
      limit: LimitParamsSchema,
      offset: OffsetParamsSchema,
      skipPagination: SkipPaginationParamsSchema,
      featureId: FeatureIdParamsSchema,
      status: StatusParamsSchema,
      author: AuthorParamsSchema,
      mine: ((schema) =>
        z.union([
          z.preprocess(
            ((read) => (val: unknown) => {
              const result = read.safeParse(val)
              return result.success ? result.data : val
            })(z.stringbool()),
            schema,
          ),
          schema,
        ]))(
        z.union([
          z.literal('true'),
          z.literal('false'),
          z.literal('0'),
          z.literal('1'),
          z.boolean(),
        ]),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'mine',
            in: 'query',
            description:
              'If true, return only revisions authored by or contributed to by the calling user.',
            schema: {
              description:
                'If true, return only revisions authored by or contributed to by the calling user.',
              anyOf: [
                { type: 'string', const: 'true' },
                { type: 'string', const: 'false' },
                { type: 'string', const: '0' },
                { type: 'string', const: '1' },
                { type: 'boolean' },
              ],
            },
            required: false,
          },
          description:
            'If true, return only revisions authored by or contributed to by the calling user.',
        }),
      archived: ((schema) =>
        z.union([
          z.preprocess(
            ((read) => (val: unknown) => {
              const result = read.safeParse(val)
              return result.success ? result.data : val
            })(z.stringbool()),
            schema,
          ),
          schema,
        ]))(
        z.union([
          z.literal('true'),
          z.literal('false'),
          z.literal('0'),
          z.literal('1'),
          z.boolean(),
        ]),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'archived',
            in: 'query',
            description:
              'Whether to include revisions for archived features. Defaults to `false` (non-archived features only). Pass `true` to include revisions for archived features alongside non-archived ones.',
            schema: {
              description:
                'Whether to include revisions for archived features. Defaults to `false` (non-archived features only). Pass `true` to include revisions for archived features alongside non-archived ones.',
              anyOf: [
                { type: 'string', const: 'true' },
                { type: 'string', const: 'false' },
                { type: 'string', const: '0' },
                { type: 'string', const: '1' },
                { type: 'boolean' },
              ],
            },
            required: false,
          },
          description:
            'Whether to include revisions for archived features. Defaults to `false` (non-archived features only). Pass `true` to include revisions for archived features alongside non-archived ones.',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              revisions: z.array(FeatureRevisionV2Schema),
              limit: z.int(),
              offset: z.int(),
              count: z.int(),
              total: z.int(),
              hasMore: z.boolean(),
              nextOffset: z.union([z.int(), z.null().nullable()]),
            })
            .openapi({
              required: ['revisions', 'limit', 'offset', 'count', 'total', 'hasMore', 'nextOffset'],
            }),
        },
      },
    },
  },
})

