export const getV2FeaturesIdRevisionsVersionDiffRoute = createRoute({
  method: 'get',
  path: '/v2/features/{id}/revisions/{version}/diff',
  tags: ['feature-revisions-v2'],
  summary: 'Diff a revision against another revision',
  description:
    "Returns a schema-keyed JSON diff between this revision and a baseline. The same shapes the in-app review surface produces under `Copy as → Minimal JSON` / `Full JSON`: `minimal` lists only what changed (with id-keyed arrays bucketed into added/removed/modified items and reorder detection), while `full` returns the complete before/after content of the revision. Lifecycle fields (version, status, comment, date, createdBy, publishedBy) are excluded from the diff body and echoed via `from` / `to` instead. Defaults to diffing against the revision's own `baseVersion`; pass `?base=live` to diff against the current live revision, or `?base=<version>` for an arbitrary historical one.",
  operationId: 'getFeatureRevisionDiffV2',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: '',
            schema: { type: 'string' },
          },
        }),
      version: VersionParamsSchema,
    }),
    query: z.object({ format: FormatParamsSchema, base: BaseParamsSchema }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z.union([
            z
              .strictObject({
                diff: z
                  .strictObject({
                    name: z.string().openapi({ description: 'The feature key.' }),
                    type: z.literal('feature'),
                    from: z
                      .int()
                      .openapi({
                        description:
                          'Version number this revision was diffed against (the before).',
                      }),
                    to: z
                      .int()
                      .openapi({ description: 'Version number being diffed (the after).' }),
                    changes: z.array(
                      z
                        .object({
                          field: z.string(),
                          change: z.enum(['added', 'removed', 'modified']),
                        })
                        .catchall(z.any())
                        .openapi({ required: ['field', 'change'] }),
                    ),
                    supplemental: z
                      .array(
                        z
                          .object({
                            name: z.string(),
                            type: z.string(),
                            change: z.enum(['added', 'removed', 'modified']),
                          })
                          .catchall(z.any())
                          .openapi({ required: ['name', 'type', 'change'] }),
                      )
                      .exactOptional(),
                  })
                  .openapi({ required: ['name', 'type', 'from', 'to', 'changes'] }),
              })
              .openapi({ required: ['diff'] }),
            z
              .strictObject({
                diff: z
                  .strictObject({
                    name: z.string().openapi({ description: 'The feature key.' }),
                    type: z.literal('feature'),
                    from: z
                      .int()
                      .openapi({
                        description:
                          'Version number this revision was diffed against (the before).',
                      }),
                    to: z
                      .int()
                      .openapi({ description: 'Version number being diffed (the after).' }),
                    before: z.record(z.string(), z.any()),
                    after: z.record(z.string(), z.any()),
                    supplemental: z
                      .array(
                        z
                          .strictObject({
                            name: z.string(),
                            type: z.string(),
                            before: z.union([z.any(), z.null().nullable()]),
                            after: z.union([z.any(), z.null().nullable()]),
                          })
                          .openapi({ required: ['name', 'type', 'before', 'after'] }),
                      )
                      .exactOptional(),
                  })
                  .openapi({ required: ['name', 'type', 'from', 'to', 'before', 'after'] }),
              })
              .openapi({ required: ['diff'] }),
          ]),
        },
      },
    },
  },
})

