export const postV2FeaturesIdRevisionsVersionRequestReviewRoute = createRoute({
  method: 'post',
  path: '/v2/features/{id}/revisions/{version}/request-review',
  tags: ['feature-revisions-v2'],
  summary: 'Request review for a draft revision',
  description:
    "Moves the draft into the `pending-review` state and notifies reviewers.\n\nSet `autoPublishOnApproval` to `true` to publish the revision automatically the moment it is approved (GitHub auto-merge model). This requires the org to have auto-publish-on-approval enabled for the feature and the caller to have publish permission; the auto-publish then executes with the caller's authority.\n\nSet `scheduledPublishAt` to a future ISO date-time to defer the auto-publish until that date (it still also requires approval when review is required). Use `scheduledPublishLockEdits` to freeze edits to this draft while the schedule is pending, and `scheduledPublishLockOthers` to block publishing other drafts of this feature in the meantime.\n\nNeither can be set on a draft whose rules would take a draft experiment live, since an automatic publish doesn't start the experiment. Schedule the experiment's start instead; starting it publishes the draft.",
  operationId: 'postFeatureRevisionRequestReviewV2',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: '',
            schema: { type: 'string' },
          },
        }),
      version: VersionParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              comment: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "Markdown. What changed and why, for reviewers. Replaces the draft's comment; leaving it out clears it.",
                }),
              autoPublishOnApproval: z.boolean().exactOptional(),
              scheduledPublishAt: z
                .union([z.iso.datetime({ offset: true }), z.null().nullable()])
                .exactOptional(),
              scheduledPublishLockEdits: z.boolean().exactOptional(),
              scheduledPublishLockOthers: z.boolean().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z
            .strictObject({ revision: FeatureRevisionV2Schema })
            .openapi({ required: ['revision'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

export const postV2FeaturesIdRevisionsVersionSchedulePublishRoute = createRoute({
  method: 'post',
  path: '/v2/features/{id}/revisions/{version}/schedule-publish',
  tags: ['feature-revisions-v2'],
  summary: 'Schedule (or cancel) a deferred publish for a draft revision',
  description:
    "Schedules the draft to publish on or after `scheduledPublishAt`. When approval is required, publishing waits until the draft is also approved. Send `scheduledPublishAt: null` to cancel the schedule.\n\nSet `lockEdits` to prevent content changes while the schedule is pending; rebasing remains allowed. Set `lockOthers` to prevent other drafts of this Feature Flag from being published until this schedule runs or is canceled. The caller needs Publish access, and that access is checked again when the schedule runs. A caller with Bypass draft approvals access can schedule an unapproved draft by sending `bypassApproval: true`. That schedule must be canceled and recreated before it can be changed, and a later edit that would reset an approval also drops the bypass.\n\nA draft whose rules would take a draft experiment live can't be scheduled, since a scheduled publish doesn't start the experiment. Schedule the experiment's start instead; starting it publishes the draft.",
  operationId: 'postFeatureRevisionSchedulePublishV2',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: '',
            schema: { type: 'string' },
          },
        }),
      version: VersionParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              scheduledPublishAt: z
                .union([z.iso.datetime({ offset: true }), z.null().nullable()])
                .openapi({
                  description:
                    'When to publish, as an RFC3339 timestamp (e.g. `2026-01-31T09:00:00Z` or `2026-01-31T02:00:00-07:00`), or `null` to cancel a pending schedule.',
                }),
              ignoreWarnings: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Set to true to acknowledge the warnings listed in a blocked response and continue. This covers experiment guards, locked dependents, and references affected by an archive. When the organization treats schema failures as warnings, it also covers schema and invariant warnings. It never bypasses a rejected Custom Hook. On revision publish endpoints, it can also force-publish an out-of-date draft when the caller has Bypass draft approvals access. Only set this when a person has explicitly asked you to. If a check blocks you, stop and ask a person instead of working around it.',
                }),
              skipSchemaValidation: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Set to true to publish despite schema validation errors, failed invariants, or schema changes that invalidate dependent resources. This does not bypass a rejected Custom Hook; use `skipHooks` for that. The caller must have Bypass draft approvals access for Feature Flags, Configs, and Constants in every Project. Otherwise, this field is ignored. Only set this when a person has explicitly asked you to. If a check blocks you, stop and ask a person instead of working around it.',
                }),
              skipHooks: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Set to true to publish despite a Custom Hook rejection. This does not bypass schema validation; use `skipSchemaValidation` for that. The caller must have Bypass draft approvals access for Feature Flags, Configs, and Constants in every Project. Otherwise, this field is ignored. Only set this when a person has explicitly asked you to. If a check blocks you, stop and ask a person instead of working around it.',
                }),
              lockEdits: z.boolean().exactOptional(),
              lockOthers: z.boolean().exactOptional(),
              bypassApproval: z.boolean().exactOptional(),
            })
            .openapi({ required: ['scheduledPublishAt'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z
            .strictObject({ revision: FeatureRevisionV2Schema })
            .openapi({ required: ['revision'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

