export const getV2FeaturesIdRevisionsVersionMergeStatusRoute = createRoute({
  method: 'get',
  path: '/v2/features/{id}/revisions/{version}/merge-status',
  tags: ['feature-revisions-v2'],
  summary: 'Get merge status for a draft revision',
  description:
    'Runs the three-way merge between the draft and the current live version without applying it. Conflicts are granular: each conflicting field gets its own key, and rules conflict individually (`rules.<ruleId>`, plus `rules.order` for competing reorders). Pass the returned `liveVersion` as `expectedLiveVersion` when rebasing. Also reports `rebaseRequired` so callers can detect ahead of time whether the publish endpoint will block until the draft is rebased.',
  operationId: 'getFeatureRevisionMergeStatusV2',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: '',
            schema: { type: 'string' },
          },
        }),
      version: VersionParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              success: z.boolean(),
              liveVersion: z
                .number()
                .openapi({
                  description:
                    'The current live version the merge was computed against. Echo this back as `expectedLiveVersion` when rebasing.',
                }),
              draftDateUpdated: z.iso
                .datetime({ offset: true })
                .openapi({
                  description:
                    "The draft's last-modified timestamp at merge time. Echo this back as `expectedDraftDateUpdated` when rebasing to guard against concurrent draft edits.",
                }),
              conflicts: z.array(ConflictsSchema),
              result: z
                .strictObject({
                  defaultValue: z.string().exactOptional(),
                  rules: z.array(z.any()).exactOptional(),
                  environmentsEnabled: z.record(z.string(), z.boolean()).exactOptional(),
                  prerequisites: z
                    .array(
                      z
                        .strictObject({ id: z.string(), condition: z.string() })
                        .openapi({ required: ['id', 'condition'] }),
                    )
                    .exactOptional(),
                  archived: z.boolean().exactOptional(),
                  metadata: z
                    .object({
                      releaseType: z.string().exactOptional(),
                      riskLevel: z.string().exactOptional(),
                    })
                    .catchall(z.any())
                    .exactOptional(),
                  holdout: z
                    .union([
                      z
                        .strictObject({ id: z.string(), value: z.string() })
                        .openapi({ required: ['id', 'value'] }),
                      z.null().nullable(),
                    ])
                    .exactOptional(),
                })
                .exactOptional()
                .openapi({ required: [] }),
              rebaseRequired: z
                .boolean()
                .openapi({
                  description:
                    'Whether the draft must be rebased before it can be published. This is true when the merge has conflicts, or when the organization requires rebasing and the draft or its approval is out of date. If there are no conflicts, a caller with Bypass draft approvals access can send `ignoreWarnings: true` to force-publish instead.',
                }),
            })
            .openapi({
              required: [
                'success',
                'liveVersion',
                'draftDateUpdated',
                'conflicts',
                'rebaseRequired',
              ],
            }),
        },
      },
    },
  },
})

export const postV2FeaturesIdRevisionsVersionRebasePreviewRoute = createRoute({
  method: 'post',
  path: '/v2/features/{id}/revisions/{version}/rebase/preview',
  tags: ['feature-revisions-v2'],
  summary: 'Preview a rebase without applying it',
  description:
    'Dry-run of the rebase: runs the same three-way merge with the supplied `conflictResolutions` and returns every conflict (resolved and unresolved) plus the merged result once all are resolved — without modifying the draft. Use it to iterate on resolutions before committing them via the rebase endpoint.',
  operationId: 'postFeatureRevisionRebasePreviewV2',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: '',
            schema: { type: 'string' },
          },
        }),
      version: VersionParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              conflictResolutions: z
                .record(z.string(), z.enum(['overwrite', 'discard']))
                .exactOptional()
                .openapi({
                  description:
                    "Map of conflict key → resolution. Keys come from the returned conflicts: `defaultValue`, `prerequisites`, `archived`, `holdout`, `environmentsEnabled.<env>`, `metadata.<field>`, `rules.<ruleId>`, and `rules.order`. `overwrite` keeps the draft's version of that item; `discard` keeps live's. The blanket `rules` key applies one strategy to all rule-level conflicts.",
                }),
              expectedLiveVersion: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'Optimistic-concurrency guard: the live version the resolutions were authored against (as returned by merge-status or rebase preview). If live has since moved, the request fails with `409` instead of applying resolutions to different conflicts.',
                }),
              expectedDraftDateUpdated: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "Optimistic-concurrency guard for the draft side: the draft's `draftDateUpdated` timestamp as returned by merge-status or rebase preview. If the draft has been modified since (e.g. by a co-author), the request fails with `409` instead of applying resolutions against changed draft content.",
                }),
              ignoreWarnings: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Set to true to acknowledge the warnings listed in a blocked response and continue. This covers experiment guards, locked dependents, and references affected by an archive. When the organization treats schema failures as warnings, it also covers schema and invariant warnings. It never bypasses a rejected Custom Hook. On revision publish endpoints, it can also force-publish an out-of-date draft when the caller has Bypass draft approvals access. Only set this when a person has explicitly asked you to. If a check blocks you, stop and ask a person instead of working around it.',
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              success: z.boolean(),
              liveVersion: z
                .number()
                .openapi({
                  description:
                    'The current live version the merge was computed against. Echo this back as `expectedLiveVersion` when rebasing.',
                }),
              draftDateUpdated: z.iso
                .datetime({ offset: true })
                .openapi({
                  description:
                    "The draft's last-modified timestamp at merge time. Echo this back as `expectedDraftDateUpdated` when rebasing to guard against concurrent draft edits.",
                }),
              conflicts: z.array(ConflictsSchema),
              result: z
                .strictObject({
                  defaultValue: z.string().exactOptional(),
                  rules: z.array(z.any()).exactOptional(),
                  environmentsEnabled: z.record(z.string(), z.boolean()).exactOptional(),
                  prerequisites: z
                    .array(
                      z
                        .strictObject({ id: z.string(), condition: z.string() })
                        .openapi({ required: ['id', 'condition'] }),
                    )
                    .exactOptional(),
                  archived: z.boolean().exactOptional(),
                  metadata: z
                    .object({
                      releaseType: z.string().exactOptional(),
                      riskLevel: z.string().exactOptional(),
                    })
                    .catchall(z.any())
                    .exactOptional(),
                  holdout: z
                    .union([
                      z
                        .strictObject({ id: z.string(), value: z.string() })
                        .openapi({ required: ['id', 'value'] }),
                      z.null().nullable(),
                    ])
                    .exactOptional(),
                })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({ required: ['success', 'liveVersion', 'draftDateUpdated', 'conflicts'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

