export const postV1ExperimentsIdStartRoute = createRoute({
  method: 'post',
  path: '/v1/experiments/{id}/start',
  tags: ['experiments'],
  summary: 'Start/Stage an experiment',
  description:
    "Starts an experiment or stages it for a future start if a `statusUpdateSchedule` is set on the experiment. Both check the launch checklist that `GET /experiments/{id}/start-checklist` returns, as gates. An incomplete item refuses the start with `checklist_incomplete` unless `skipChecklist` is set; a linked Feature Flag blocker refuses it either way. The refusal lists each blocking gate in `gates`, with the flag or permission that gets past it and a route that resolves it. A linked Feature Flag draft that still needs approval, or a flag locked by a ramp, is bypassed automatically when the caller has Bypass draft approvals access for that flag or the organization enables the REST API approval bypass. A start reports what it got past in `bypassedGates` and the drafts it published in `publishedFeatureDrafts`; if a draft can't publish, for example because it needs a rebase, the start fails with `pending_draft_publish_failed` before any is published. A staged start carries the caller's Bypass draft approvals access to when it runs, for the drafts as they were when it was staged: if one has changed since, or the caller has lost that access, it needs approval like any other. The organization's REST API approval bypass doesn't carry to a staged start.",
  operationId: 'postExperimentStart',
  request: {
    params: z.object({ id: IdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              skipChecklist: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'If true, skips validating the experiment satisfies all pre-launch checklist items. Only set this when a person has explicitly asked you to. If a check blocks you, stop and ask a person instead of working around it.',
                }),
              bypassApproval: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Deprecated and ignored. Approval is bypassed automatically when the caller has Bypass draft approvals access for this resource or when the organization enables the REST API approval bypass. Otherwise, the revision must be approved before it can be published.',
                }),
              ignoreWarnings: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Set to true to acknowledge the warnings listed in a blocked response and continue. This covers experiment guards, locked dependents, and references affected by an archive. When the organization treats schema failures as warnings, it also covers schema and invariant warnings. It never bypasses a rejected Custom Hook. On revision publish endpoints, it can also force-publish an out-of-date draft when the caller has Bypass draft approvals access. Only set this when a person has explicitly asked you to. If a check blocks you, stop and ask a person instead of working around it.',
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              experiment: ExperimentWithEnhancedStatusSchema,
              message: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Present only when the request staged a future scheduled start instead of starting the experiment immediately.',
                }),
              bypassedGates: z
                .array(
                  z
                    .strictObject({
                      key: z
                        .string()
                        .openapi({
                          description:
                            'The checklist item, or `rampLocked:<featureId>` for a linked Feature Flag a ramp locks.',
                        }),
                      type: z
                        .string()
                        .openapi({
                          description:
                            'Gate kind: "checklist-item", "approval-required", "merge-conflict", "unrelated-draft-changes", "permission-denied" or "ramp-locked".',
                        }),
                      outcome: z.literal('bypassed'),
                      via: z
                        .enum([
                          'ignoreWarnings',
                          'skipSchemaValidation',
                          'skipHooks',
                          'bypassApprovalPermission',
                          'restApiBypassesReviews',
                          'revertsBypassApproval',
                          'skipChecklist',
                        ])
                        .openapi({
                          description:
                            "How it was passed: `skipChecklist`, the caller's permission (`bypassApprovalPermission`), or the organization's REST API approval bypass (`restApiBypassesReviews`).",
                        }),
                    })
                    .openapi({ required: ['key', 'type', 'outcome', 'via'] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Gates this start skipped or bypassed. Present only when there were some.',
                }),
              publishedFeatureDrafts: z
                .array(PublishedFeatureDraftsSchema)
                .exactOptional()
                .openapi({
                  description:
                    'The linked Feature Flag drafts the start published. Present only when it published some.',
                }),
            })
            .openapi({ required: ['experiment'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
    409: {
      description: 'Conflict',
      content: {
        'application/json': {
          schema: z.xor([
            z
              .object({
                message: z.string(),
                code: z.literal('checklist_incomplete'),
                details: ApiErrorChecklistIncompleteDetailsSchema,
              })
              .openapi({
                description:
                  'An experiment start is blocked by its launch checklist or a linked Feature Flag',
                required: ['message', 'code', 'details'],
              }),
            z
              .object({
                message: z.string(),
                code: z.literal('pending_draft_publish_failed'),
                details: ApiErrorPendingDraftPublishFailedDetailsSchema,
              })
              .openapi({
                description: 'One or more linked feature drafts could not be published',
                required: ['message', 'code', 'details'],
              }),
            z
              .object({
                message: z.string(),
                code: z.literal('invalid_status'),
                details: ApiErrorInvalidStatusDetailsSchema,
              })
              .openapi({
                description: 'Resource is not in a valid status for this operation',
                required: ['message', 'code', 'details'],
              }),
          ]),
        },
      },
    },
  },
})

