export const putV1ExperimentsIdScheduleRoute = createRoute({
  method: 'put',
  path: '/v1/experiments/{id}/schedule',
  tags: ['experiments'],
  summary: "Set an experiment's schedule and shipping automation",
  description:
    "Full-replace of the experiment's scheduled start/end and end-of-experiment shipping automation. The body is the complete desired state: any omitted field is cleared (omit `startAt` to remove a scheduled start; send an empty body to clear the whole schedule). Provide either `stopAt` or `stopAfter`, not both; a relative `stopAfter` resolves to a concrete stop when the experiment starts. Setting a scheduled end (`stopAt` or `stopAfter`) requires a `scheduledStopPlan` (any mode, including `notify`). The scheduled end must be in the future: a `stopAt` (or a `stopAfter` that resolves) in the past is rejected — including one whose end date has already passed and been acted on, so changing the plan after a soft end requires committing to a new end date. Auto-ship shipping requires the Decision Framework.",
  operationId: 'putExperimentSchedule',
  request: {
    params: z.object({ id: IdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              startAt: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    'ISO datetime when the experiment should start; must be in the future. Omit to clear a scheduled start. Staging still happens via POST /experiments/{id}/start.',
                }),
              stopAt: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({ description: 'Absolute ISO datetime to stop the experiment.' }),
              stopAfter: z
                .strictObject({ value: z.int().gt(0), unit: z.enum(['hours', 'days']) })
                .exactOptional()
                .openapi({
                  description:
                    "Deferred relative end, resolved to a concrete stop at the experiment's actual start (or now, if already running).",
                  required: ['value', 'unit'],
                }),
              scheduledStopPlan: ScheduledStopPlanSchema.exactOptional().openapi({
                description:
                  'End-of-experiment automation. Required whenever a `stopAt` or `stopAfter` is set (any mode, including `notify`).',
              }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource updated',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              experiment: ExperimentWithEnhancedStatusSchema,
              warnings: z.array(z.string()).exactOptional(),
            })
            .openapi({ required: ['experiment'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
    409: {
      description: 'Conflict',
      content: {
        'application/json': {
          schema: z
            .object({
              message: z.string(),
              code: z.literal('invalid_status'),
              details: ApiErrorInvalidStatusDetailsSchema,
            })
            .openapi({
              description: 'Resource is not in a valid status for this operation',
              required: ['message', 'code', 'details'],
            }),
        },
      },
    },
  },
})

