export const getV1ContextualBanditsIdSnapshotsRoute = createRoute({
  method: 'get',
  path: '/v1/contextual-bandits/{id}/snapshots',
  tags: ['ContextualBandits'],
  summary: 'List Contextual Bandit snapshots',
  operationId: 'listContextualBanditSnapshots',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: 'The Contextual Bandit id',
            schema: { description: 'The Contextual Bandit id', type: 'string' },
          },
          description: 'The Contextual Bandit id',
        }),
    }),
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().gt(0).max(100),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: '',
            schema: { type: 'integer', exclusiveMinimum: 0, maximum: 100 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z
            .strictObject({ snapshots: z.array(SnapshotsSchema) })
            .openapi({ required: ['snapshots'] }),
        },
      },
    },
  },
})

