export const getV1ContextualBanditsIdResultsRoute = createRoute({
  method: 'get',
  path: '/v1/contextual-bandits/{id}/results',
  tags: ['ContextualBandits'],
  summary: 'Get latest Contextual Bandit results',
  description:
    'Returns the latest contextual-bandit stats engine output (per-context responses tagged with their leaf, the per-leaf targeting conditions, and per-leaf aggregated stats), the overall (marginal) variation weights across all contexts, the health checks (traffic, SRM, multiple exposures) computed by that same run, and the status of the most recent snapshot run for the contextual bandit. Same payload the GrowthBook UI uses to render the contextual bandit results and health tabs.',
  operationId: 'getContextualBanditResults',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: 'The Contextual Bandit id',
            schema: { description: 'The Contextual Bandit id', type: 'string' },
          },
          description: 'The Contextual Bandit id',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              contextualBanditSnapshot: z.union([
                z
                  .strictObject({
                    attributes: z.array(z.string()),
                    responses: z.array(z.any()),
                    leaf_map: z.array(z.any()).exactOptional(),
                    leaf_stats: z.array(z.any()).exactOptional(),
                    sse_trajectory: z.array(z.any()).exactOptional(),
                    bic_trajectory: z.array(z.any()).exactOptional(),
                  })
                  .openapi({ required: ['attributes', 'responses'] }),
                z.null().nullable(),
              ]),
              overallWeights: z.union([
                z.array(
                  z
                    .strictObject({
                      variationId: z.string(),
                      weight: z.union([z.number(), z.null().nullable()]),
                    })
                    .openapi({ required: ['variationId', 'weight'] }),
                ),
                z.null().nullable(),
              ]),
              results: z.union([
                z
                  .strictObject({
                    attributes: z.array(z.string()),
                    sseTrajectory: z.array(
                      z
                        .strictObject({
                          numSplits: z.int().min(0),
                          totalSse: z.number(),
                          split: z
                            .strictObject({
                              leafClauses: z.array(
                                z
                                  .strictObject({
                                    attribute: z.string(),
                                    levels: z.array(z.string()),
                                    operator: z.enum(['in', 'not in']),
                                  })
                                  .openapi({ required: ['attribute', 'levels', 'operator'] }),
                              ),
                              attribute: z.string(),
                              leftLevels: z.array(z.string()),
                              rightLevels: z.array(z.string()),
                            })
                            .exactOptional()
                            .openapi({
                              required: ['leafClauses', 'attribute', 'leftLevels', 'rightLevels'],
                            }),
                        })
                        .openapi({ required: ['numSplits', 'totalSse'] }),
                    ),
                    overall: z
                      .strictObject({
                        variations: z.array(
                          z
                            .strictObject({
                              variationId: z.string(),
                              variationName: z.string().exactOptional(),
                              weight: z.union([z.number(), z.null().nullable()]),
                              mean: z.union([z.number(), z.null().nullable()]),
                              users: z.union([z.number(), z.null().nullable()]),
                            })
                            .openapi({ required: ['variationId', 'weight', 'mean', 'users'] }),
                        ),
                      })
                      .openapi({ required: ['variations'] }),
                    leaves: z.array(
                      z
                        .strictObject({
                          leafId: z.int(),
                          updateMessage: z.union([z.string(), z.null().nullable()]),
                          error: z.union([z.string(), z.null().nullable()]),
                          clauses: z.array(
                            z
                              .strictObject({
                                attribute: z.string(),
                                levels: z.array(z.string()),
                                operator: z.enum(['in', 'not in']),
                              })
                              .openapi({ required: ['attribute', 'levels', 'operator'] }),
                          ),
                          variations: z.array(
                            z
                              .strictObject({
                                variationId: z.string(),
                                variationName: z.string().exactOptional(),
                                weight: z.union([z.number(), z.null().nullable()]),
                                bestArmProbability: z.union([z.number(), z.null().nullable()]),
                                users: z.union([z.number(), z.null().nullable()]),
                                mean: z.union([z.number(), z.null().nullable()]),
                                variance: z.union([z.number(), z.null().nullable()]),
                              })
                              .openapi({
                                required: [
                                  'variationId',
                                  'weight',
                                  'bestArmProbability',
                                  'users',
                                  'mean',
                                  'variance',
                                ],
                              }),
                          ),
                          contexts: z.array(
                            z
                              .strictObject({
                                attributes: z.record(z.string(), z.string()),
                                variations: z.array(
                                  z
                                    .strictObject({
                                      variationId: z.string(),
                                      variationName: z.string().exactOptional(),
                                      users: z.union([z.number(), z.null().nullable()]),
                                      mean: z.union([z.number(), z.null().nullable()]),
                                      variance: z.union([z.number(), z.null().nullable()]),
                                    })
                                    .openapi({
                                      required: ['variationId', 'users', 'mean', 'variance'],
                                    }),
                                ),
                              })
                              .openapi({ required: ['attributes', 'variations'] }),
                          ),
                        })
                        .openapi({
                          required: [
                            'leafId',
                            'updateMessage',
                            'error',
                            'clauses',
                            'variations',
                            'contexts',
                          ],
                        }),
                    ),
                    snapshotId: z.string(),
                    dateCreated: z.string(),
                    health: z.union([
                      z
                        .strictObject({
                          variations: z.array(
                            z
                              .strictObject({
                                variationId: z.string(),
                                variationName: z.string().exactOptional(),
                                weight: z.number(),
                              })
                              .openapi({ required: ['variationId', 'weight'] }),
                          ),
                          traffic: z.union([
                            z
                              .strictObject({
                                overall: z
                                  .strictObject({
                                    name: z.string(),
                                    srm: z.number(),
                                    variationUnits: z.array(z.number()),
                                  })
                                  .openapi({ required: ['name', 'srm', 'variationUnits'] }),
                                dimension: z.record(
                                  z.string(),
                                  z.array(
                                    z
                                      .strictObject({
                                        name: z.string(),
                                        srm: z.number(),
                                        variationUnits: z.array(z.number()),
                                      })
                                      .openapi({ required: ['name', 'srm', 'variationUnits'] }),
                                  ),
                                ),
                                error: z.string().exactOptional(),
                              })
                              .openapi({ required: ['overall', 'dimension'] }),
                            z.null().nullable(),
                          ]),
                          srm: z.union([
                            z
                              .strictObject({
                                statistic: z.number(),
                                pValue: z.number(),
                                degreesOfFreedom: z.int().min(0),
                                latestPeriod: z
                                  .strictObject({
                                    banditVersion: z.string(),
                                    leaves: z.array(
                                      z
                                        .strictObject({
                                          leafId: z.string(),
                                          observed: z.array(z.number()),
                                          expected: z.array(z.number()),
                                        })
                                        .openapi({ required: ['leafId', 'observed', 'expected'] }),
                                    ),
                                  })
                                  .exactOptional()
                                  .openapi({ required: ['banditVersion', 'leaves'] }),
                              })
                              .openapi({ required: ['statistic', 'pValue', 'degreesOfFreedom'] }),
                            z.null().nullable(),
                          ]),
                          multipleExposures: z.union([z.number(), z.null().nullable()]),
                        })
                        .openapi({
                          required: ['variations', 'traffic', 'srm', 'multipleExposures'],
                        }),
                      z.null().nullable(),
                    ]),
                  })
                  .openapi({
                    required: [
                      'attributes',
                      'sseTrajectory',
                      'overall',
                      'leaves',
                      'snapshotId',
                      'dateCreated',
                      'health',
                    ],
                  }),
                z.null().nullable(),
              ]),
              latest: z.union([
                z
                  .strictObject({
                    id: z.string(),
                    status: z.enum(['running', 'success', 'error']),
                    error: z.string(),
                    queries: z.array(
                      z
                        .strictObject({
                          query: z.string(),
                          status: z.enum([
                            'queued',
                            'running',
                            'failed',
                            'partially-succeeded',
                            'succeeded',
                          ]),
                          name: z.string(),
                        })
                        .openapi({ required: ['query', 'status', 'name'] }),
                    ),
                    runStarted: z.union([z.string(), z.null().nullable()]),
                    dateCreated: z.string(),
                    multipleExposures: z.number(),
                    type: z.string(),
                    triggeredBy: z.string(),
                  })
                  .openapi({
                    required: [
                      'id',
                      'status',
                      'error',
                      'queries',
                      'runStarted',
                      'dateCreated',
                      'multipleExposures',
                      'type',
                      'triggeredBy',
                    ],
                  }),
                z.null().nullable(),
              ]),
            })
            .openapi({
              required: ['contextualBanditSnapshot', 'overallWeights', 'results', 'latest'],
            }),
        },
      },
    },
  },
})

