export const postV1SegmentsRoute = createRoute({
  method: 'post',
  path: '/v1/segments',
  tags: ['segments'],
  summary: 'Create a single segment',
  operationId: 'postSegment',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              name: z
                .string()
                .openapi({ description: 'Short display name. Put details in `description`.' }),
              owner: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The userId or email address of the owner. If an email address is provided, it will be used to look up the userId of the matching organization member. If an ID is provided, it will be validated as existing in the organization.',
                }),
              description: z
                .string()
                .max(10000)
                .exactOptional()
                .openapi({ description: 'Description of the segment' }),
              datasourceId: z
                .string()
                .openapi({ description: 'ID of the datasource this segment belongs to' }),
              identifierType: z
                .string()
                .openapi({ description: 'Type of identifier (user, anonymous, etc.)' }),
              projects: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description: 'List of project IDs for projects that can access this segment',
                }),
              managedBy: z
                .enum(['', 'api'])
                .exactOptional()
                .openapi({
                  description:
                    'Where this Segment must be managed from. If not set (empty string), it can be managed from anywhere.',
                }),
              type: z
                .enum(['SQL', 'FACT'])
                .openapi({
                  description:
                    'GrowthBook supports two types of Segments, SQL and FACT. SQL segments are defined by a SQL query, and FACT segments are defined by a fact table and filters.',
                }),
              query: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'SQL query that defines the Segment. This is required for SQL segments.',
                }),
              factTableId: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'ID of the fact table this segment belongs to. This is required for FACT segments.',
                }),
              filters: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'Optional array of fact table filter ids that can further define the Fact Table based Segment.',
                }),
            })
            .openapi({ required: ['name', 'datasourceId', 'identifierType', 'type'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z.strictObject({ segment: SegmentSchema }).openapi({ required: ['segment'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

