export const postV1AttributesRoute = createRoute({
  method: 'post',
  path: '/v1/attributes',
  tags: ['attributes'],
  summary: 'Create a new attribute',
  operationId: 'postAttribute',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              property: z
                .string()
                .openapi({
                  description:
                    "Attribute name exactly as your SDK passes it (e.g. `userId`). The API can't rename it, and renaming it in the UI doesn't update SDK code or targeting conditions.",
                }),
              datatype: z
                .enum([
                  'boolean',
                  'string',
                  'number',
                  'secureString',
                  'enum',
                  'string[]',
                  'number[]',
                  'secureString[]',
                ])
                .openapi({ description: 'The attribute datatype' }),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'Markdown. Put context here, not in the name.' }),
              archived: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'The attribute is archived' }),
              hashAttribute: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Shall the attribute be hashed' }),
              enum: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "Comma-separated list of allowed values. Required for the 'enum' datatype. For array datatypes (string[], number[], secureString[]) it optionally restricts the list to these values. Ignored for all other datatypes.",
                }),
              format: z
                .enum(['', 'version', 'date', 'isoCountryCode'])
                .exactOptional()
                .openapi({ description: "The attribute's format" }),
              projects: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    "Project IDs that can use this. An empty list means all Projects. Projects control access and availability, so don't use them as labels.",
                }),
              tags: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'Tags for filtering and grouping. Use these instead of encoding groups in names.',
                }),
              customFields: z
                .record(z.string(), z.string())
                .exactOptional()
                .openapi({
                  description:
                    "Values for the organization's attribute custom fields, keyed by field id",
                }),
            })
            .openapi({ required: ['property', 'datatype'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z
            .strictObject({ attribute: AttributeSchema })
            .openapi({ required: ['attribute'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

