export const putV1VisualChangesetsIdRoute = createRoute({
  method: 'put',
  path: '/v1/visual-changesets/{id}',
  tags: ['visual-changesets'],
  summary: 'Update a visual changeset',
  operationId: 'putVisualChangeset',
  request: {
    params: z.object({ id: IdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              editorUrl: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'URL of the page opened in the visual editor when creating this changeset',
                }),
              urlPatterns: z
                .array(
                  z
                    .object({
                      include: z.boolean().exactOptional(),
                      type: z.enum(['simple', 'regex']),
                      pattern: z.string(),
                    })
                    .catchall(z.any())
                    .openapi({ required: ['type', 'pattern'] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'URL patterns that determine which pages this visual changeset applies to',
                }),
              allowRunningExperiment: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    "Also accept the write when the experiment is running. Off by default so a stale editor can't change a live test. When set, the change reaches live traffic immediately and the caller needs the runExperiments permission on the affected environments; the write is audited.",
                }),
              visualChanges: z
                .array(
                  z
                    .object({
                      id: z.string().exactOptional(),
                      description: z.string().exactOptional(),
                      css: z.string().exactOptional(),
                      js: z.string().exactOptional(),
                      variation: z.string(),
                      domMutations: z
                        .array(
                          z
                            .object({
                              selector: z.string(),
                              action: z.enum(['append', 'set', 'remove']),
                              attribute: z.string(),
                              value: z.string().exactOptional(),
                              parentSelector: z.string().exactOptional(),
                              insertBeforeSelector: z.string().exactOptional(),
                            })
                            .catchall(z.any())
                            .openapi({ required: ['selector', 'action', 'attribute'] }),
                        )
                        .exactOptional(),
                    })
                    .catchall(z.any())
                    .openapi({ required: ['variation'] }),
                )
                .exactOptional(),
            })
            .catchall(z.any()),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource updated',
      content: {
        'application/json': {
          schema: z
            .strictObject({ nModified: z.number(), visualChangeset: VisualChangesetSchema })
            .openapi({ required: ['nModified', 'visualChangeset'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

