export const postV1SavedGroupsIdUploadsVersionLoadsRoute = createRoute({
  method: 'post',
  path: '/v1/saved-groups/{id}/uploads/{version}/loads',
  tags: ['saved-groups'],
  summary: 'Report loading a remote saved group upload into a data store',
  description:
    'Called by remote saved group loaders. Each report replaces the previous one from the same `storeId`. Needs permission to publish the saved group.',
  operationId: 'postSavedGroupUploadLoad',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: 'The id of the remote saved group',
            schema: { description: 'The id of the remote saved group', type: 'string' },
          },
          description: 'The id of the remote saved group',
        }),
      version: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().gt(0),
        )
        .openapi({
          param: {
            name: 'version',
            in: 'path',
            required: true,
            description: '',
            schema: { type: 'integer', exclusiveMinimum: 0 },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              storeId: z
                .string()
                .min(1)
                .max(100)
                .openapi({
                  description:
                    "The data store's ID, such as `redis-us-east`, set in the loader's config. Loaders sharing a store (such as one Redis) use the same ID. Shown in the UI.",
                }),
              status: z
                .union([
                  z.strictObject({ type: z.literal('loading') }).openapi({ required: ['type'] }),
                  z
                    .strictObject({
                      type: z.literal('loaded'),
                      rowCount: z.int().min(0).openapi({ description: 'Unique IDs loaded' }),
                    })
                    .openapi({ required: ['type', 'rowCount'] }),
                  z
                    .strictObject({
                      type: z.literal('invalid'),
                      invalidLineCount: z.int().min(0),
                      errors: z
                        .array(z.string().max(500))
                        .max(10)
                        .openapi({ description: 'The first problems found in the file' }),
                    })
                    .openapi({
                      description:
                        'The file has problems, so the store kept serving the previous upload',
                      required: ['type', 'invalidLineCount', 'errors'],
                    }),
                  z
                    .strictObject({
                      type: z.literal('failed'),
                      error: z
                        .string()
                        .max(2000)
                        .openapi({ description: 'A problem in the data store, not the file' }),
                    })
                    .openapi({ required: ['type', 'error'] }),
                ])
                .openapi({
                  description:
                    'Loaders validate the file while loading it, so each store reports its own result.',
                }),
            })
            .openapi({ required: ['storeId', 'status'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z
            .strictObject({ upload: SavedGroupUploadSchema })
            .openapi({ required: ['upload'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

