export const postV1ConstantsRoute = createRoute({
  method: 'post',
  path: '/v1/constants',
  tags: ['constants'],
  summary: 'Create a single constant',
  operationId: 'postConstant',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              key: z
                .string()
                .regex(/^[a-z0-9][a-z0-9\-_]*$/)
                .openapi({
                  description:
                    'Stable reference handle (lowercase slug, unique per org), referenced as `@const:key`',
                }),
              name: z.string().openapi({ description: 'The display name of the constant' }),
              type: z
                .enum(['string', 'json'])
                .openapi({
                  description:
                    '`string` (interpolated as `{{ @const:key }}`) or `json` (substituted as a whole value)',
                }),
              value: z.string().exactOptional(),
              environmentValues: z.record(z.string(), z.string()).exactOptional(),
              description: z
                .string()
                .max(10000)
                .exactOptional()
                .openapi({ description: 'Markdown. Put context here, not in the name.' }),
              project: z.string().exactOptional(),
              owner: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The userId or email address of the owner. If an email address is provided, it will be used to look up the userId of the matching organization member. If an ID is provided, it will be validated as existing in the organization. When omitted, it defaults to the requesting member: a personal access token's owner, or the member an organization API key assumes. An organization API key acting as itself leaves it empty.",
                }),
            })
            .openapi({ required: ['key', 'name', 'type'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z.strictObject({ constant: ConstantSchema }).openapi({ required: ['constant'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

export const getV1ConstantsRevisionsRoute = createRoute({
  method: 'get',
  path: '/v1/constants-revisions',
  tags: ['constant-revisions'],
  summary: 'List constant revisions across the organization',
  description:
    "Returns a paginated list of revisions across all constants in the organization, sorted newest-first. Optionally filtered by constant, status, author, or the calling user's involvement.",
  operationId: 'listConstantRevisions',
  request: {
    query: z.object({
      limit: LimitParamsSchema,
      offset: OffsetParamsSchema,
      skipPagination: SkipPaginationParamsSchema,
      key: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'key',
            in: 'query',
            description:
              'Restrict results to revisions for a single constant (by its key). When omitted, returns revisions across every constant the caller can read.',
            schema: {
              description:
                'Restrict results to revisions for a single constant (by its key). When omitted, returns revisions across every constant the caller can read.',
              type: 'string',
            },
            required: false,
          },
          description:
            'Restrict results to revisions for a single constant (by its key). When omitted, returns revisions across every constant the caller can read.',
        }),
      status: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            description:
              'Filter by revision status. Accepts a comma-separated list, or the literal `open` for non-merged/non-discarded revisions.',
            schema: {
              description:
                'Filter by revision status. Accepts a comma-separated list, or the literal `open` for non-merged/non-discarded revisions.',
              type: 'string',
            },
            required: false,
          },
          description:
            'Filter by revision status. Accepts a comma-separated list, or the literal `open` for non-merged/non-discarded revisions.',
        }),
      author: AuthorParamsSchema,
      mine: ((schema) =>
        z.union([
          z.preprocess(
            ((read) => (val: unknown) => {
              const result = read.safeParse(val)
              return result.success ? result.data : val
            })(z.stringbool()),
            schema,
          ),
          schema,
        ]))(
        z.union([
          z.literal('true'),
          z.literal('false'),
          z.literal('0'),
          z.literal('1'),
          z.boolean(),
        ]),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'mine',
            in: 'query',
            description:
              "If true, return only revisions authored by the calling user. Needs a personal access token, or an organization API key that assumes a named member's role. Mutually exclusive with `author`.",
            schema: {
              description:
                "If true, return only revisions authored by the calling user. Needs a personal access token, or an organization API key that assumes a named member's role. Mutually exclusive with `author`.",
              anyOf: [
                { type: 'string', const: 'true' },
                { type: 'string', const: 'false' },
                { type: 'string', const: '0' },
                { type: 'string', const: '1' },
                { type: 'boolean' },
              ],
            },
            required: false,
          },
          description:
            "If true, return only revisions authored by the calling user. Needs a personal access token, or an organization API key that assumes a named member's role. Mutually exclusive with `author`.",
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              revisions: z.array(ConstantRevisionSchema),
              limit: z.int(),
              offset: z.int(),
              count: z.int(),
              total: z.int(),
              hasMore: z.boolean(),
              nextOffset: z.union([z.int(), z.null().nullable()]),
            })
            .openapi({
              required: ['revisions', 'limit', 'offset', 'count', 'total', 'hasMore', 'nextOffset'],
            }),
        },
      },
    },
  },
})

