export const getV1ConstantsRevisionsKeyRoute = createRoute({
  method: 'get',
  path: '/v1/constants-revisions/{key}',
  tags: ['constant-revisions'],
  summary: 'List revisions for a constant',
  description:
    "Returns a paginated list of revisions for this constant, sorted newest-first. Optionally filtered by status, author, or the calling user's involvement.",
  operationId: 'getConstantRevisions',
  request: {
    params: z.object({
      key: z
        .string()
        .openapi({
          param: {
            name: 'key',
            in: 'path',
            required: true,
            description: '',
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      limit: LimitParamsSchema,
      offset: OffsetParamsSchema,
      skipPagination: SkipPaginationParamsSchema,
      status: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            description:
              'Filter by revision status. Accepts a comma-separated list, or the literal `open` for non-merged/non-discarded revisions.',
            schema: {
              description:
                'Filter by revision status. Accepts a comma-separated list, or the literal `open` for non-merged/non-discarded revisions.',
              type: 'string',
            },
            required: false,
          },
          description:
            'Filter by revision status. Accepts a comma-separated list, or the literal `open` for non-merged/non-discarded revisions.',
        }),
      author: AuthorParamsSchema,
      mine: ((schema) =>
        z.union([
          z.preprocess(
            ((read) => (val: unknown) => {
              const result = read.safeParse(val)
              return result.success ? result.data : val
            })(z.stringbool()),
            schema,
          ),
          schema,
        ]))(
        z.union([
          z.literal('true'),
          z.literal('false'),
          z.literal('0'),
          z.literal('1'),
          z.boolean(),
        ]),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'mine',
            in: 'query',
            description:
              "If true, return only revisions authored by the calling user. Needs a personal access token, or an organization API key that assumes a named member's role. Mutually exclusive with `author`.",
            schema: {
              description:
                "If true, return only revisions authored by the calling user. Needs a personal access token, or an organization API key that assumes a named member's role. Mutually exclusive with `author`.",
              anyOf: [
                { type: 'string', const: 'true' },
                { type: 'string', const: 'false' },
                { type: 'string', const: '0' },
                { type: 'string', const: '1' },
                { type: 'boolean' },
              ],
            },
            required: false,
          },
          description:
            "If true, return only revisions authored by the calling user. Needs a personal access token, or an organization API key that assumes a named member's role. Mutually exclusive with `author`.",
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              revisions: z.array(ConstantRevisionSchema),
              limit: z.int(),
              offset: z.int(),
              count: z.int(),
              total: z.int(),
              hasMore: z.boolean(),
              nextOffset: z.union([z.int(), z.null().nullable()]),
            })
            .openapi({
              required: ['revisions', 'limit', 'offset', 'count', 'total', 'hasMore', 'nextOffset'],
            }),
        },
      },
    },
  },
})

