export const putV1ConstantsRevisionsKeyVersionMetadataRoute = createRoute({
  method: 'put',
  path: '/v1/constants-revisions/{key}/{version}/metadata',
  tags: ['constant-revisions'],
  summary: 'Update constant metadata in a draft revision',
  description:
    'Stages metadata changes (name, owner, description, project) on the draft. Pass `version: "new"` to auto-create a draft. The change is only applied to the live constant when the revision is merged.',
  operationId: 'putConstantRevisionMetadata',
  request: {
    params: z.object({
      key: z
        .string()
        .openapi({
          param: {
            name: 'key',
            in: 'path',
            required: true,
            description: '',
            schema: { type: 'string' },
          },
        }),
      version: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(z.union([z.int(), z.literal('new')])).openapi({
        param: {
          name: 'version',
          in: 'path',
          required: true,
          description: '',
          schema: { anyOf: [{ type: 'integer' }, { type: 'string', const: 'new' }] },
        },
      }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              revisionTitle: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Short draft title (e.g. `Enable for beta testers`). Only used when `version` is "new"; ignored for existing drafts.',
                }),
              revisionComment: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Markdown. What changed and why, for reviewers. Only used when `version` is "new"; ignored for existing drafts.',
                }),
              name: z
                .string()
                .exactOptional()
                .openapi({ description: 'Short display name. Put details in `description`.' }),
              owner: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The userId or email address of the owner. If an email address is provided, it will be used to look up the userId of the matching organization member. If an ID is provided, it will be validated as existing in the organization.',
                }),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'Markdown. Put context here, not in the name.' }),
              project: z.string().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource updated',
      content: {
        'application/json': {
          schema: z
            .strictObject({ revision: ConstantRevisionSchema })
            .openapi({ required: ['revision'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

