export const postV1FactTablesIdRoute = createRoute({
  method: 'post',
  path: '/v1/fact-tables/{id}',
  tags: ['fact-tables'],
  summary: 'Update a single fact table',
  operationId: 'updateFactTable',
  request: {
    params: z.object({ id: IdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              name: z
                .string()
                .exactOptional()
                .openapi({ description: 'Short display name. Put details in `description`.' }),
              description: z
                .string()
                .max(10000)
                .exactOptional()
                .openapi({ description: 'Markdown. Put context here, not in the name.' }),
              owner: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The userId or email address of the owner. If an email address is provided, it will be used to look up the userId of the matching organization member. If an ID is provided, it will be validated as existing in the organization.',
                }),
              projects: z
                .array(z.string())
                .exactOptional()
                .openapi({ description: 'List of associated project ids' }),
              tags: z
                .array(z.string())
                .exactOptional()
                .openapi({ description: 'List of associated tags' }),
              userIdTypes: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'List of identifier columns in this table. For example, "id" or "anonymous_id"',
                }),
              userIdColumns: z
                .record(z.string(), z.string())
                .exactOptional()
                .openapi({
                  description:
                    'Maps an identifier type to the column holding it, for SQL that does not alias its columns to the identifier type names, e.g. `{"user_id": "userId"}`. May also be a single-level field path into a JSON column (`properties.userId`). Unmapped types use the identifier type name as the column name.',
                }),
              aggregatedFactTableSettings: z
                .strictObject({
                  idTypes: z.array(z.string()),
                  updateTime: z
                    .strictObject({ time: z.string(), timezone: z.string() })
                    .openapi({ required: ['time', 'timezone'] }),
                  lookbackWindow: z.int().gt(0),
                  restateChunkDays: z.int().min(1).max(7).exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Settings for maintaining shared daily aggregated tables (a subset of userIdTypes plus the daily update time and restate lookback window) used to speed up CUPED. Requires the data pipeline (pipeline-mode) feature.',
                  required: ['idTypes', 'updateTime', 'lookbackWindow'],
                }),
              sql: z
                .string()
                .exactOptional()
                .openapi({ description: 'The SQL query for this fact table' }),
              timestampColumn: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The column holding the event timestamp. Must be a date column on this fact table. Defaults to "timestamp" when unset.',
                }),
              eventName: z
                .string()
                .exactOptional()
                .openapi({ description: 'The event name used in SQL template variables' }),
              columns: z
                .array(FactTableColumnInputSchema)
                .exactOptional()
                .openapi({
                  description:
                    'Optional array of columns to upsert by `column`: existing columns are patched, new columns are created, and columns not included are left unchanged. Omit `datatype` to leave an existing column\'s type untouched; send "" to reset it for auto-detection; new columns are auto-detected when `datatype` is omitted or "". Slice-related properties require an enterprise license.',
                }),
              managedBy: z
                .enum(['', 'api', 'admin', 'dbt'])
                .exactOptional()
                .openapi({
                  description:
                    'Set this to "api" (or "dbt" for resources synced from dbt) to disable editing in the GrowthBook UI',
                }),
              archived: z.boolean().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z
            .strictObject({ factTable: FactTableSchema })
            .openapi({ required: ['factTable'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

