export const postV1MembersIdRoleRoute = createRoute({
  method: 'post',
  path: '/v1/members/{id}/role',
  tags: ['members'],
  summary: "Update a member's role",
  description:
    "Update a member's global role (including any environment restrictions, if applicable). Can also update a member's project roles if your plan supports it.",
  operationId: 'updateMemberRole',
  request: {
    params: z.object({ id: IdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              member: z
                .strictObject({
                  role: z.string().exactOptional(),
                  environments: z.array(z.string()).exactOptional(),
                  additionalRoles: z
                    .array(
                      z
                        .strictObject({
                          role: z.string(),
                          environments: z.array(z.string()),
                          limitAccessByEnvironment: z.boolean().exactOptional(),
                        })
                        .openapi({ required: ['role', 'environments'] }),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        'Additional roles granted alongside this one, in the same scope. Each is granted independently and environment access is the union across them.',
                    }),
                  projectRoles: z
                    .array(
                      z
                        .strictObject({
                          project: z.string(),
                          role: z.string(),
                          environments: z.array(z.string()),
                          limitAccessByEnvironment: z.boolean().exactOptional(),
                          additionalRoles: z
                            .array(
                              z
                                .strictObject({
                                  role: z.string(),
                                  environments: z.array(z.string()),
                                  limitAccessByEnvironment: z.boolean().exactOptional(),
                                })
                                .openapi({ required: ['role', 'environments'] }),
                            )
                            .exactOptional()
                            .openapi({
                              description:
                                'Additional roles granted alongside this one, in the same scope. Each is granted independently and environment access is the union across them.',
                            }),
                        })
                        .openapi({ required: ['project', 'role', 'environments'] }),
                    )
                    .exactOptional(),
                })
                .openapi({ required: [] }),
            })
            .openapi({ required: ['member'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z
            .strictObject({ updatedMember: UpdatedMemberSchema })
            .openapi({ required: ['updatedMember'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

