export const postV1RampSchedulesActionsRollbackRoute = createRoute({
  method: 'post',
  path: '/v1/ramp-schedules/actions/rollback',
  tags: ['ramp-schedules'],
  summary: 'Roll back matching ramp schedules',
  description:
    "Rolls back every `running` or `paused` ramp schedule that matches the query\nfilters. Built for an alerting tool's webhook, such as a Datadog monitor.\n\nEach filter takes comma-separated values and matches any of them; different\nfilters must all match. At least one filter is required.\n\nReturns each matched schedule and whether the rollback was applied or skipped,\nfor example because the API key can't publish its Feature Flag. Unknown body\nfields are ignored, so a tool can send its own payload.\n",
  operationId: 'rollbackMatchingRampSchedules',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['customFields']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          environment: z
            .preprocess(
              (val) =>
                val === undefined
                  ? val
                  : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                      typeof item === 'string' ? item.split(',') : [item],
                    ),
              z.array(z.string()),
            )
            .exactOptional()
            .openapi({
              param: {
                name: 'environment',
                in: 'query',
                description:
                  'Comma-separated environments. Matches ramps whose rules run in any of them.',
                schema: {
                  description:
                    'Comma-separated environments. Matches ramps whose rules run in any of them.',
                  type: 'array',
                  items: { type: 'string' },
                },
                explode: false,
                required: false,
              },
              description:
                'Comma-separated environments. Matches ramps whose rules run in any of them.',
            }),
          project: ProjectParamsSchema,
          tag: z
            .preprocess(
              (val) =>
                val === undefined
                  ? val
                  : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                      typeof item === 'string' ? item.split(',') : [item],
                    ),
              z.array(z.string()),
            )
            .exactOptional()
            .openapi({
              param: {
                name: 'tag',
                in: 'query',
                description:
                  'Comma-separated tags. Matches ramps on Feature Flags with any of them.',
                schema: {
                  description:
                    'Comma-separated tags. Matches ramps on Feature Flags with any of them.',
                  type: 'array',
                  items: { type: 'string' },
                },
                explode: false,
                required: false,
              },
              description: 'Comma-separated tags. Matches ramps on Feature Flags with any of them.',
            }),
          feature: FeatureParamsSchema,
          customFields: CustomFieldsParamsSchema,
          reason: ReasonParamsSchema,
        }),
      ),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              reason: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Recorded on each ramp, prefixed with `Alert: `. Use the alert title and link.',
                }),
            })
            .catchall(z.any()),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z
            .strictObject({ rampSchedules: z.array(MatchedRampScheduleSchema) })
            .openapi({ required: ['rampSchedules'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

