export const postV1ReportsRoute = createRoute({
  method: 'post',
  path: '/v1/reports',
  tags: ['reports'],
  summary: 'Create a new report',
  operationId: 'postReport',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              experimentId: z
                .string()
                .openapi({ description: 'The experiment to create a report for' }),
              title: z
                .string()
                .exactOptional()
                .openapi({ description: 'Report title (defaults to experiment name)' }),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'Report description' }),
              owner: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The userId or email address of the owner. If an email address is provided, it will be used to look up the userId of the matching organization member. If an ID is provided, it will be validated as existing in the organization. When omitted, it defaults to the requesting member: a personal access token's owner, or the member an organization API key assumes. An organization API key acting as itself leaves it empty.",
                }),
              statsEngine: z
                .enum(['bayesian', 'frequentist'])
                .exactOptional()
                .openapi({ description: 'Stats engine override' }),
              goalMetrics: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description: "Goal metric IDs (defaults to experiment's goal metrics)",
                }),
              secondaryMetrics: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description: "Secondary metric IDs (defaults to experiment's secondary metrics)",
                }),
              guardrailMetrics: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description: "Guardrail metric IDs (defaults to experiment's guardrail metrics)",
                }),
              activationMetric: z
                .string()
                .exactOptional()
                .openapi({ description: 'Activation metric ID' }),
              dimension: z
                .string()
                .exactOptional()
                .openapi({ description: 'Dimension to cut results by' }),
              dateStarted: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({ description: 'Analysis start date (ISO 8601)' }),
              dateEnded: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({ description: 'Analysis end date (ISO 8601)' }),
              regressionAdjustmentEnabled: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Enable CUPED regression adjustment' }),
              sequentialTestingEnabled: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Enable sequential testing' }),
              sequentialTestingTuningParameter: z
                .number()
                .exactOptional()
                .openapi({
                  description: 'Tuning parameter for sequential testing (frequentist only)',
                }),
              differenceType: z
                .enum(['relative', 'absolute', 'scaled'])
                .exactOptional()
                .openapi({
                  description:
                    'How lifts are expressed in results. Defaults to experiment setting.',
                }),
              attributionModel: z
                .enum(['firstExposure', 'experimentDuration', 'lookbackOverride'])
                .exactOptional()
                .openapi({
                  description:
                    'Metric conversion window attribution model. Defaults to experiment setting.',
                }),
              lookbackOverride: z
                .union([
                  z
                    .strictObject({ type: z.literal('date'), value: z.any() })
                    .openapi({ required: ['type', 'value'] }),
                  z
                    .strictObject({
                      type: z.literal('window'),
                      value: z.number().min(0),
                      valueUnit: z.enum(['minutes', 'hours', 'days', 'weeks']),
                    })
                    .openapi({ required: ['type', 'value', 'valueUnit'] }),
                ])
                .exactOptional()
                .openapi({
                  description: 'Lookback window when `attributionModel` is `lookbackOverride`',
                }),
              metricOverrides: z
                .array(
                  z
                    .strictObject({
                      id: z.string(),
                      windowType: z.enum(['conversion', 'lookback', '']).exactOptional(),
                      windowHours: z.number().exactOptional(),
                      delayHours: z.number().exactOptional(),
                      properPriorOverride: z.boolean().exactOptional(),
                      properPriorEnabled: z.boolean().exactOptional(),
                      properPriorMean: z.number().exactOptional(),
                      properPriorStdDev: z.number().gt(0).exactOptional(),
                      regressionAdjustmentOverride: z.boolean().exactOptional(),
                      regressionAdjustmentEnabled: z.boolean().exactOptional(),
                      regressionAdjustmentDays: z.number().exactOptional(),
                      winRisk: z
                        .number()
                        .exactOptional()
                        .openapi({
                          deprecated: true,
                          description: 'No longer used. Accepted and ignored.',
                        }),
                      loseRisk: z
                        .number()
                        .exactOptional()
                        .openapi({
                          deprecated: true,
                          description: 'No longer used. Accepted and ignored.',
                        }),
                    })
                    .openapi({ required: ['id'] }),
                )
                .exactOptional()
                .openapi({
                  description: 'Per-metric window, prior, and regression-adjustment overrides',
                }),
              customMetricSlices: z
                .array(
                  z
                    .strictObject({
                      slices: z.array(
                        z
                          .strictObject({ column: z.string(), levels: z.array(z.string()) })
                          .openapi({ required: ['column', 'levels'] }),
                      ),
                    })
                    .openapi({ required: ['slices'] }),
                )
                .exactOptional()
                .openapi({ description: 'Custom metric slice definitions' }),
              segment: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Segment ID to filter users by. Defaults to experiment setting.',
                }),
              queryFilter: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Raw SQL WHERE clause added to the exposure query. Defaults to experiment setting.',
                }),
              skipPartialData: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'When true, exclude users who have not completed the full conversion window.',
                }),
              shareLevel: z
                .enum(['public', 'organization', 'private'])
                .exactOptional()
                .openapi({
                  description:
                    'Visibility of the created report. Defaults to `private`. Set to `public` to receive a shareable `shareUrl` in the response.',
                }),
            })
            .openapi({ required: ['experimentId'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z.strictObject({ report: ReportSchema }).openapi({ required: ['report'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

