export const putV1InterleavingsIdRoute = createRoute({
  method: 'put',
  path: '/v1/interleavings/{id}',
  tags: ['Interleavings'],
  summary: 'Update a single interleaving',
  description:
    'Archive an interleaving experiment by setting `archived`. Use the start and stop endpoints to change its status.',
  operationId: 'updateInterleaving',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: '',
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              name: z.string().exactOptional(),
              description: z.string().max(10000).exactOptional(),
              project: z.string().exactOptional(),
              owner: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The userId or email address of the owner. If an email address is provided, it will be used to look up the userId of the matching organization member. If an ID is provided, it will be validated as existing in the organization.',
                }),
              tags: z.array(z.string()).exactOptional(),
              archived: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Stop a running interleaving experiment before archiving it.',
                }),
              trackingKey: z.string().exactOptional(),
              hashAttribute: z.string().exactOptional(),
              seed: z.string().exactOptional(),
              variations: z
                .array(z.unknown())
                .superRefine((arr, ctx) => {
                  const Prefix = [
                    z
                      .strictObject({
                        key: z.string().regex(/\S/),
                        name: z.string(),
                        description: z.string().max(10000).exactOptional(),
                        config: z
                          .string()
                          .openapi({
                            description:
                              "The ranker's config, as a JSON string. Passed to `getList` in the SDK.",
                          }),
                      })
                      .openapi({ required: ['key', 'name', 'config'] }),
                    z
                      .strictObject({
                        key: z.string().regex(/\S/),
                        name: z.string(),
                        description: z.string().max(10000).exactOptional(),
                        config: z
                          .string()
                          .openapi({
                            description:
                              "The ranker's config, as a JSON string. Passed to `getList` in the SDK.",
                          }),
                      })
                      .openapi({ required: ['key', 'name', 'config'] }),
                  ]
                  for (const [i, Schema] of Prefix.slice(0, arr.length).entries()) {
                    const result = Schema.safeParse(arr[i])
                    if (!result.success) {
                      for (const issue of result.error.issues) {
                        ctx.addIssue({ ...issue, path: [i, ...issue.path] })
                      }
                    }
                  }
                })
                .exactOptional()
                .openapi({
                  description:
                    'Replaces both rankers. Each keeps its id by position, so the first entry updates the first ranker.',
                }),
              jsonSchema: z
                .union([
                  z
                    .strictObject({
                      schemaType: z.enum(['schema', 'simple']),
                      schema: z.string(),
                      simple: z
                        .strictObject({
                          type: z.enum(['object', 'object[]', 'primitive', 'primitive[]']),
                          fields: z.array(
                            z
                              .strictObject({
                                key: z.string().max(64),
                                type: z.enum(['integer', 'float', 'string', 'boolean']),
                                required: z.boolean(),
                                default: z.string().max(256),
                                description: z.string().max(10000),
                                enum: z.array(z.string().max(256)).max(256),
                                min: z.number().exactOptional(),
                                max: z.number().exactOptional(),
                                nullable: z.boolean().exactOptional(),
                                jsonSchema: z.string().exactOptional(),
                              })
                              .openapi({
                                required: [
                                  'key',
                                  'type',
                                  'required',
                                  'default',
                                  'description',
                                  'enum',
                                ],
                              }),
                          ),
                          additionalProperties: z.boolean().exactOptional(),
                          invariants: z
                            .array(
                              z
                                .strictObject({
                                  name: z.string().max(128),
                                  rule: z.string(),
                                  message: z.string().max(10000),
                                })
                                .openapi({ required: ['name', 'rule', 'message'] }),
                            )
                            .exactOptional(),
                        })
                        .openapi({ required: ['type', 'fields'] }),
                      enabled: z.boolean(),
                    })
                    .openapi({
                      description:
                        "Validation schema to stage on the draft. The server sets `date`, so don't send it.",
                      required: ['schemaType', 'schema', 'simple', 'enabled'],
                    }),
                  z.null().nullable(),
                ])
                .exactOptional(),
              datasource: z.string().exactOptional(),
              interleavingQueryId: z.string().exactOptional(),
              userIdType: z.string().exactOptional(),
              metrics: z
                .array(
                  z
                    .strictObject({
                      id: z.string(),
                      analyses: z
                        .array(
                          z.union([
                            z
                              .strictObject({ type: z.literal('paired') })
                              .openapi({ required: ['type'] }),
                            z
                              .strictObject({
                                type: z.literal('ownership'),
                                attribution: z.enum(['exposureCount', 'engagementSignal']),
                              })
                              .openapi({ required: ['type', 'attribution'] }),
                          ]),
                        )
                        .min(1),
                    })
                    .openapi({ required: ['id', 'analyses'] }),
                )
                .exactOptional(),
              coverage: z.number().min(0).max(1).exactOptional(),
              condition: z.string().exactOptional(),
              savedGroups: z
                .array(
                  z
                    .strictObject({
                      match: z.enum(['all', 'none', 'any']),
                      ids: z.array(z.string()),
                    })
                    .openapi({ required: ['match', 'ids'] }),
                )
                .exactOptional(),
              prerequisites: z
                .array(
                  z
                    .strictObject({ id: z.string(), condition: z.string() })
                    .openapi({ required: ['id', 'condition'] }),
                )
                .exactOptional(),
              environmentSettings: z
                .record(
                  z.string(),
                  z.strictObject({ enabled: z.boolean() }).openapi({ required: ['enabled'] }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource updated',
      content: {
        'application/json': {
          schema: z
            .strictObject({ interleaving: InterleavingSchema })
            .openapi({ required: ['interleaving'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

