                          '<=',
                          '>',
                          '>=',
                          'between',
                          'not_between',
                          'in',
                          'not_in',
                          'contains',
                          'not_contains',
                          'matches_pattern',
                          'not_matches_pattern',
                          'starts_with',
                          'ends_with',
