export const postV1PopulationsRoute = createRoute({
  method: 'post',
  path: '/v1/populations',
  tags: ['Populations'],
  summary: 'Create a single population',
  operationId: 'createPopulation',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              name: z.string().min(1),
              description: z.string().exactOptional(),
              owner: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The userId or email address of the owner. If an email address is provided, it will be used to look up the userId of the matching organization member. If an ID is provided, it will be validated as existing in the organization. When omitted, it defaults to the requesting member: a personal access token's owner, or the member an organization API key assumes. An organization API key acting as itself must send it, or the request fails with a 400.",
                }),
              projects: z.array(z.string()).exactOptional(),
              datasource: z.string().openapi({ description: 'Id of the Data Source' }),
              userIdTypes: z
                .array(z.string())
                .min(1)
                .openapi({
                  description:
                    "Identifier types the Population can be joined on. Every step's fact table must support all of them",
                }),
              steps: z
                .array(
                  z
                    .strictObject({
                      source: z.union([
                        z
                          .strictObject({ type: z.literal('factTable'), factTableId: z.string() })
                          .openapi({ required: ['type', 'factTableId'] }),
                      ]),
                      rowFilters: z
                        .array(
                          z
                            .strictObject({
                              operator: z.enum([
                                '=',
                                '!=',
                                '<',
                                '<=',
                                '>',
                                '>=',
                                'between',
                                'not_between',
                                'in',
                                'not_in',
                                'contains',
                                'not_contains',
                                'matches_pattern',
                                'not_matches_pattern',
                                'starts_with',
                                'ends_with',
                                'is_null',
                                'not_null',
                                'is_true',
                                'is_false',
                                'sql_expr',
                                'saved_filter',
                              ]),
                              column: z.string().exactOptional(),
                              values: z.array(z.string()).exactOptional(),
                            })
                            .openapi({ required: ['operator'] }),
                        )
                        .exactOptional(),
                      aggregateFilter: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'Conditions on each unit\'s total within the queried date range, such as ">=3" or ">=3,<10". Requires aggregateFilterColumn',
                        }),
                      aggregateFilterColumn: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'Numeric column to total, or "$$count" to count rows. Requires aggregateFilter',
                        }),
                    })
                    .openapi({ required: ['source'] }),
                )
                .length(1)
                .openapi({
                  description:
                    'Steps a unit must complete, in order, to be included. Currently limited to 1 step with support for multiple steps coming soon.',
                }),
            })
            .openapi({
              description: 'Create a Population',
              required: ['name', 'datasource', 'userIdTypes', 'steps'],
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: z
            .strictObject({ population: PopulationSchema })
            .openapi({ required: ['population'] }),
        },
      },
    },
    202: ConfirmationHeldResponse,
  },
})

